CREATE INDEX ix_trades_date     ON trades(trade_date);
CREATE INDEX ix_trades_exchange ON trades(exchange_id, trade_date);
CREATE INDEX ix_trades_product  ON trades(product_id);
CREATE INDEX ix_trades_buyer    ON trades(buyer_id);
CREATE INDEX ix_trades_seller   ON trades(seller_id);
CREATE INDEX ix_trades_bbroker  ON trades(buyer_broker_id);
CREATE INDEX ix_trades_sbroker  ON trades(seller_broker_id);
CREATE INDEX ix_trades_amount   ON trades(amount);
CREATE INDEX ix_trades_terms    ON trades(delivery_terms);
CREATE INDEX ix_participants_bin  ON participants(bin);
CREATE INDEX ix_products_name     ON products(name);
COMMIT;
